style.css:
/* BABY BLUE DREAM — GLOBAL STYLISH THEME */
/* Safe version (won’t break sites) */

/* ===== PAGE BACKGROUND ===== */
html, body {
  background-image: url("https://i.pinimg.com/736x/14/f5/97/14f5974fa53af984c4e7461161c92889.jpg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  color: #1f2a44 !important;
}

/* ===== SOFT OVERLAY (SAFE) ===== */
html::before {
  content: "";
  position: fixed;
  inset: 0;
  background-color: rgba(234, 244, 255, 0.88);
  pointer-events: none; /* prevents clicking issues */
  z-index: 0;
}

/* ===== KEEP CONTENT ABOVE OVERLAY ===== */
body > * {
  position: relative;
  z-index: 1;
}

/* ===== GENERAL ELEMENTS ===== */
* {
  border-color: #c7dcf5 !important;
}

/* ===== INPUTS ===== */
textarea,
input,
select {
  background-color: rgba(245, 250, 255, 0.95) !important;
  color: #1f2a44 !important;
  border-radius: 14px !important;
}

/* ===== BUTTONS ===== */
button {
  background-color: #9ecbff !important;
  color: #0b1d3a !important;
  border-radius: 16px !important;
  font-weight: 600 !important;
}

button:hover {
  background-color: #b7dcff !important;
}

/* ===== LINKS ===== */
a {
  color: #5a8fdc !important;
}
